	// ---------------------------------------------------------------------------
	// Default annotations — major pre-K policy events
	// ---------------------------------------------------------------------------
	const DEFAULT_ANNOTATIONS = [
		{
			date: '2013-02-13',
			label: 'Obama SOTU — universal pre-K proposal',
			major: false,
			side: 'right'
		},
		{ date: '2014-01-28', label: 'Obama SOTU — pre-K follow-up', major: false, side: 'right' },
		{ date: '2015-05-16', label: 'Senate pre-K bill introduced', major: false, side: 'left' },
		{
			date: '2015-09-29',
			label: 'Child care funding legislation vote',
			major: false,
			side: 'right'
		},
		{
			date: '2019-01-22',
			label: 'State pre-K expansions (NY, CO, others)',
			major: false,
			side: 'left'
		},
		{
			date: '2021-04-28',
			label: 'Biden — American Families Plan\n$200B for universal pre-K',
			major: true,
			side: 'left'
		},
		{ date: '2021-10-28', label: 'Build Back Better negotiations', major: false, side: 'right' }
	];

	export let data = PRE_K_DATA;
	export let annotations = DEFAULT_ANNOTATIONS;
	export let threshold = 10;
	export let thresholdLabel = '10 stories/day';

	export let title = 'Day 13: Ecosystems - Media Ecosystems on Early childhood education policy ';
	export let subtitle =
		'Pre-K coverage in 2025 is 41% below its pre-Biden baseline. The debate briefly inflated interest, then exhausted it.';
	export let source =
		'MediaCloud · query: "universal pre-K" OR "early childhood education policy" OR "preschool funding" OR "universal preschool" OR "childcare policy"';
	export let width = 960;
	export let height = 560;

	// ---------------------------------------------------------------------------
	// Brand colours
	// ---------------------------------------------------------------------------
	const C = {
		sage: '#3D5C3A',
		sagePale: 'rgba(61,92,58,0.16)',
		warmGray: '#8A8780',
		warmPale: 'rgba(138,135,128,0.09)',
		amber: '#C47A2B',
		ink: '#1C2B1A',
		gridLine: '#E5E3DC'
	};

	let container;
	onMount(() => {
		draw();
	});

	// ---------------------------------------------------------------------------
	// Draw
	// ---------------------------------------------------------------------------
	function draw() {
		if (!container || !data || !data.length) return;
		d3.select(container).selectAll('*').remove();

		// --- Parse data ---
		const parseDate = d3.timeParse('%Y-%m-%d');
		const pts = data
			.map((d) => ({ date: parseDate(d.date), count: +d.count, smooth: +d.smooth }))
			.filter((d) => d.date && !isNaN(d.smooth))
			.sort((a, b) => a.date - b.date);

		const annParsed = (annotations || DEFAULT_ANNOTATIONS).map((a) => ({
			...a,
			dateObj: parseDate(a.date)
		}));

		// Build raw count lookup by date string
		const countMap = {};
		pts.forEach((p) => {
			const key = d3.timeFormat('%Y-%m-%d')(p.date);
			countMap[key] = p.count;
		});

		// --- Layout ---
		const TITLE_H = 80;
		const DB_H = 44;
		const DB_GAP = 16;
		const FOOTER_H = spacing.marginDefault.bottom;
		const MAP_TOP = TITLE_H + DB_H + DB_GAP;
		const ML = spacing.marginDefault.left;
		const MR = spacing.marginDefault.right;
		const cW = width - ML - MR;
		const PAD = { t: 28, b: 40 };
		const cH = height - MAP_TOP - FOOTER_H - PAD.b;

		const svgH = height;

		// --- Scales ---
		const xSc = d3
			.scaleTime()
			.domain(d3.extent(pts, (d) => d.date))
			.range([0, cW]);

		const yMax = Math.ceil(d3.max(pts, (d) => d.smooth) / 10) * 10 + 8;
		const ySc = d3.scaleLinear().domain([0, yMax]).range([cH, 0]);

		const ty = ySc(threshold); // y-pixel of threshold

		// --- SVG ---
		const svg = d3
			.select(container)
			.append('svg')
			.attr('width', width)
			.attr('height', svgH)
			.attr('viewBox', `0 0 ${width} ${svgH}`)
			.attr('role', 'img')
			.attr(
				'aria-label',
				`${title} — line chart showing daily story counts with 7-day rolling average`
			)
			.style('background', colors.canvas)
			.style('font-family', type.sans)
			.style('max-width', '100%')
			.style('height', 'auto');

		// --- Furniture ---
		addFurniture(svg, { width, height: svgH, title, subtitle, source });

		// --- Databox ---
		const box = addDataBox(svg, {
			width,
			height: svgH,
			fields: ['date', 'avg', 'count', 'event'],
			total: null,
			y: TITLE_H + 4
		});

		// --- Plot group ---
		const g = svg.append('g').attr('transform', `translate(${ML}, ${MAP_TOP})`);

		// Clip
		const clipId = 'vl-mac-clip';
		svg
			.append('defs')
			.append('clipPath')
			.attr('id', clipId)
			.append('rect')
			.attr('x', 0)
			.attr('y', 0)
			.attr('width', cW)
			.attr('height', cH);

		const plotG = g.append('g').attr('clip-path', `url(#${clipId})`);

		// --- Area fills ---
		// Below threshold — warm grey
		const areaBelowFn = d3
			.area()
			.x((d) => xSc(d.date))
			.y0(cH)
			.y1((d) => Math.min(ySc(d.smooth), ty))
			.curve(d3.curveMonotoneX);

		// Above threshold — sage green
		const areaAboveFn = d3
			.area()
			.x((d) => xSc(d.date))
			.y0((d) => Math.max(ySc(d.smooth), ty))
			.y1((d) => Math.min(ySc(d.smooth), ty))
			.curve(d3.curveMonotoneX);

		plotG
			.append('path')
			.datum(pts)
			.attr('d', areaBelowFn)
			.attr('fill', C.warmPale)
			.attr('pointer-events', 'none');

		plotG
			.append('path')
			.datum(pts)
			.attr('d', areaAboveFn)
			.attr('fill', C.sagePale)
			.attr('pointer-events', 'none');

		// --- Grid lines & y-axis ---
		const yTicks = ySc.ticks(6);
		yTicks.forEach((t) => {
			g.append('line')
				.attr('x1', 0)
				.attr('x2', cW)
				.attr('y1', ySc(t))
				.attr('y2', ySc(t))
				.attr('stroke', colors.gridLine)
				.attr('stroke-width', 0.75)
				.attr('pointer-events', 'none');

			g.append('text')
				.attr('x', -6)
				.attr('y', ySc(t))
				.attr('text-anchor', 'end')
				.attr('dominant-baseline', 'middle')
				.style('font-size', '11px')
				.style('fill', colors.warmGray)
				.text(t);
		});

		// --- x-axis year labels ---
		const xTicks = d3.timeYear.every(1).range(...xSc.domain());
		xTicks.forEach((t) => {
			g.append('text')
				.attr('x', xSc(t))
				.attr('y', cH + 16)
				.attr('text-anchor', 'middle')
				.style('font-size', '11px')
				.style('fill', colors.warmGray)
				.text(t.getFullYear());

			g.append('line')
				.attr('x1', xSc(t))
				.attr('x2', xSc(t))
				.attr('y1', cH)
				.attr('y2', cH + 4)
				.attr('stroke', colors.gridLine)
				.attr('stroke-width', 0.75);
		});

		// --- Threshold dashed line ---
		g.append('line')
			.attr('x1', 0)
			.attr('x2', cW)
			.attr('y1', ty)
			.attr('y2', ty)
			.attr('stroke', C.amber)
			.attr('stroke-width', 1.2)
			.attr('stroke-dasharray', '5,4')
			.attr('pointer-events', 'none');

		g.append('text')
			.attr('x', 4)
			.attr('y', ty - 4)
			.style('font-size', '11px')
			.style('fill', C.amber)
			.text(thresholdLabel);

		// --- Annotations (event lines) ---
		annParsed.forEach((ann) => {
			if (!ann.dateObj) return;
			const ax = xSc(ann.dateObj);
			const ap = pts.find((p) => Math.abs(p.date - ann.dateObj) < 4 * 864e5);
			const ay = ap ? ySc(ap.smooth) : 0;

			// Vertical dashed line
			g.append('line')
				.attr('x1', ax)
				.attr('x2', ax)
				.attr('y1', ay)
				.attr('y2', cH)
				.attr('stroke', ann.major ? C.amber : C.warmGray)
				.attr('stroke-width', ann.major ? 1.2 : 0.75)
				.attr('stroke-dasharray', '3,3')
				.attr('pointer-events', 'none');

			// Dot at line
			g.append('circle')
				.attr('cx', ax)
				.attr('cy', ay)
				.attr('r', ann.major ? 4 : 2.5)
				.attr('fill', ann.major ? C.amber : C.warmGray)
				.attr('pointer-events', 'none');

			// Short label above chart top (rotated for readability)
			if (ann.major) {
				const lines = ann.label.split('\n');
				const lx = ax + (ann.side === 'left' ? -6 : 6);
				const anchor = ann.side === 'left' ? 'end' : 'start';
				lines.forEach((ln, li) => {
					g.append('text')
						.attr('x', lx)
						.attr('y', Math.max(ay - 18 - li * 13, PAD.t - li * 12))
						.attr('text-anchor', anchor)
						.style('font-size', '10px')
						.style('font-weight', 500)
						.style('fill', C.amber)
						.text(ln);
				});
			}
		});

		// --- Main line ---
		const lineFn = d3
			.line()
			.x((d) => xSc(d.date))
			.y((d) => ySc(d.smooth))
			.curve(d3.curveMonotoneX);

		plotG
			.append('path')
			.datum(pts)
			.attr('d', lineFn)
			.attr('fill', 'none')
			.attr('stroke', C.sage)
			.attr('stroke-width', 1.75)
			.attr('pointer-events', 'none');

		// --- Legend ---
		const legY = MAP_TOP + cH + PAD.b - 4;
		const legItems = [
			{ label: '7-day avg', color: C.sage, type: 'line' },
			{ label: `Above ${threshold} stories/day`, color: C.sagePale, type: 'rect' },
			{ label: `Below ${threshold} stories/day`, color: C.warmPale, type: 'rect' },
			{ label: `${thresholdLabel} threshold`, color: C.amber, type: 'dash' }
		];
		let lx = ML;
		legItems.forEach((item) => {
			const lg = svg.append('g').attr('transform', `translate(${lx}, ${legY})`);
			if (item.type === 'line') {
				lg.append('line')
					.attr('x1', 0)
					.attr('x2', 16)
					.attr('y1', 5)
					.attr('y2', 5)
					.attr('stroke', item.color)
					.attr('stroke-width', 2);
			} else if (item.type === 'dash') {
				lg.append('line')
					.attr('x1', 0)
					.attr('x2', 16)
					.attr('y1', 5)
					.attr('y2', 5)
					.attr('stroke', item.color)
					.attr('stroke-width', 1.5)
					.attr('stroke-dasharray', '4,3');
			} else {
				lg.append('rect')
					.attr('x', 0)
					.attr('y', 0)
					.attr('width', 16)
					.attr('height', 10)
					.attr('rx', 2)
					.attr('fill', item.color)
					.attr('stroke', colors.warmGray)
					.attr('stroke-width', 0.5);
			}
			const txt = lg
				.append('text')
				.attr('x', 20)
				.attr('y', 8)
				.style('font-size', '11px')
				.style('fill', colors.warmGray)
				.text(item.label);
			const tw = txt.node().getComputedTextLength
				? txt.node().getComputedTextLength()
				: item.label.length * 6;
			lx += 20 + tw + 16;
		});

		// --- Interaction: hover + click ---
		let activeIdx = null; // pinned data point index
		const fmtDate = d3.timeFormat('%b %-d, %Y');
		const bisect = d3.bisector((d) => d.date).left;

		// Cursor line + dot
		const cursorLine = g
			.append('line')
			.attr('y1', 0)
			.attr('y2', cH)
			.attr('stroke', colors.warmGray)
			.attr('stroke-width', 0.75)
			.attr('stroke-dasharray', '4,3')
			.style('opacity', 0)
			.attr('pointer-events', 'none');

		const cursorDot = g
			.append('circle')
			.attr('r', 5)
			.attr('fill', C.sage)
			.attr('stroke', colors.canvas)
			.attr('stroke-width', 1.5)
			.style('opacity', 0)
			.attr('pointer-events', 'none');

		// Find nearest annotation for a data point
		function findAnn(pt) {
			const ms7 = 7 * 864e5;
			return annParsed.find((a) => a.dateObj && Math.abs(a.dateObj - pt.date) < ms7);
		}

		function showPoint(pt, pinned) {
			const x = xSc(pt.date);
			const y = ySc(pt.smooth);
			cursorLine.attr('x1', x).attr('x2', x).style('opacity', 0.5);
			cursorDot
				.attr('cx', x)
				.attr('cy', y)
				.style('opacity', 1)
				.attr('fill', pt.smooth > threshold ? C.sage : C.warmGray);

			const dateStr = d3.timeFormat('%Y-%m-%d')(pt.date);
			const ann = findAnn(pt);
			box.show({
				date: fmtDate(pt.date),
				avg: pt.smooth.toFixed(2) + ' stories (avg)',
				count: (countMap[dateStr] ?? pt.count) + ' stories (raw)',
				event: ann ? ann.label.replace('\n', ' — ') : '—',
				value: pt.smooth,
				name: fmtDate(pt.date)
			});
			box.setColor(pt.smooth > threshold ? C.sage : C.warmGray);
		}

		function clearHover() {
			cursorLine.style('opacity', 0);
			cursorDot.style('opacity', 0);
			box.clear();
		}

		// Hit area
		const hit = g
			.append('rect')
			.attr('x', 0)
			.attr('y', 0)
			.attr('width', cW)
			.attr('height', cH)
			.attr('fill', 'transparent')
			.style('cursor', 'crosshair');

		hit
			.on('mousemove', function (event) {
				if (activeIdx !== null) return;
				const [mx] = d3.pointer(event, this);
				const date = xSc.invert(mx);
				const idx = Math.max(0, Math.min(pts.length - 1, bisect(pts, date, 1)));
				const i =
					idx > 0 && Math.abs(pts[idx - 1].date - date) < Math.abs(pts[idx].date - date)
						? idx - 1
						: idx;
				showPoint(pts[i], false);
			})
			.on('mouseleave', () => {
				if (activeIdx === null) clearHover();
			})
			.on('click', function (event) {
				event.stopPropagation();
				const [mx] = d3.pointer(event, this);
				const date = xSc.invert(mx);
				const idx = Math.max(0, Math.min(pts.length - 1, bisect(pts, date, 1)));
				const i =
					idx > 0 && Math.abs(pts[idx - 1].date - date) < Math.abs(pts[idx].date - date)
						? idx - 1
						: idx;
				if (activeIdx === i) {
					activeIdx = null;
					clearHover();
				} else {
					activeIdx = i;
					showPoint(pts[i], true);
				}
			});

		svg.on('click', () => {
			if (activeIdx !== null) {
				activeIdx = null;
				clearHover();
			}
		});
		container.addEventListener('mouseleave', () => {
			if (activeIdx === null) clearHover();
		});
	}
</script>

<div bind:this={container} style="position: relative; width: 100%; margin: 2rem 0;" />
